node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Check products table schema
const schema = db.prepare(\"PRAGMA table_info('products')\").all();
console.log('Products schema:', schema);
console.log('---');

// Search for Everyday Crew Tee
const rows = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Crew Tee%' OR name LIKE '%Everyday%'\").all();
console.log('Products matching:', JSON.stringify(rows, null, 2));
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Check rt_variants for the product
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = '2460285426'\").all();
console.log('Variants:', JSON.stringify(variants, null, 2));

// Check promotions
const promos = db.prepare(\"SELECT * FROM promotions\").all();
console.log('---');
console.log('Promotions:', JSON.stringify(promos, null, 2));

// Check if there are similar products for comparison
const similar = db.prepare(\"SELECT product_id, name, brand, price, current_price, previous_price, category, subcategory, rating, review_count, in_stock FROM products WHERE category = 'clothing' AND (name LIKE '%Tee%' OR name LIKE '%T-Shirt%' OR name LIKE '%Crew%')\").all();
console.log('---');
console.log('Similar clothing (tees):', JSON.stringify(similar, null, 2));
"
